head.b:skin:
html,body{margin:0;padding:0;background:#0a0a0a}
body{color:#f4efe8;font-family:'Bricolage Grotesque',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;line-height:1.6;min-height:100vh}
#navbar,.feed-links,#Blog1{display:none!important}
.page{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:32px 22px;box-sizing:border-box}
.brand{font-weight:800;letter-spacing:.3em;font-size:.85rem;color:#8a8580;margin-bottom:34px}
.brand b{color:#c8ff3a}
h1{font-size:clamp(2.2rem,9vw,4.2rem);line-height:1.05;margin:0 0 16px;font-weight:800;letter-spacing:-.02em}
p.sub{color:#a9a39b;max-width:460px;margin:0 auto 34px;font-size:1.05rem}
a.play{display:inline-block;background:#c8ff3a;color:#0a0a0a;text-decoration:none;font-weight:800;letter-spacing:.25em;font-size:1rem;padding:20px 44px;border-radius:999px}
a.play:active{transform:scale(.97)}
a.play:focus{outline:2px solid #f4efe8;outline-offset:4px}
.tag{margin-top:36px;color:#8a8580;font-size:.9rem}
.posts{display:none}
